class Solution {
public:
    long long minimumCost(string s) {
        long long ans = 0;
        int n = s.size();
        for (int i = 0; i < n - 1; ++i) {
            if (s[i] != s[i + 1]) {
                ans += min(i + 1, n - 1 - i);
            }
        }
        return ans;
    }
};

class Solution {
    public long minimumCost(String s) {
        long ans = 0;
        int n = s.length();
        for (int i = 0; i < n - 1; i++) {
            if (s.charAt(i) != s.charAt(i + 1)) {
                ans += Math.min(i + 1, n - 1 - i);
            }
        }
        return ans;
    }
}

var minimumCost = function(s) {
    let ans = 0;
